-- coroutine.close: suspended, dead, errored, running and normal coroutines, with to-be-closed variables.
local function closer(name)
  return setmetatable({}, {__close = function(_, e) print("close", name, e) end})
end
-- closing a suspended coroutine runs its pending __close in reverse order
local co = coroutine.create(function()
  local a <close> = closer("a")
  local b <close> = closer("b")
  coroutine.yield("suspended with two")
  print("never here")
end)
print(coroutine.resume(co))
print(coroutine.close(co))
print(coroutine.status(co))
print(coroutine.resume(co))
-- closing again, and closing a coroutine that never started or that finished
print(coroutine.close(co))
print(coroutine.close(coroutine.create(print)))
local done = coroutine.create(function() return 1 end)
coroutine.resume(done)
print(coroutine.close(done))
-- closing a coroutine that died with an error returns false and the error
local bad = coroutine.create(function() error("died") end)
print(coroutine.resume(bad))
print(coroutine.close(bad))
print(coroutine.close(bad))
local badt = coroutine.create(function() error({}) end)
coroutine.resume(badt)
local ok, e = coroutine.close(badt)
print(ok, type(e))
-- a __close that errors while closing: close returns false and that error
local co2 = coroutine.create(function()
  local x <close> = setmetatable({}, {__close = function() error("close failed", 0) end})
  local y <close> = closer("y")
  coroutine.yield()
end)
coroutine.resume(co2)
print(coroutine.close(co2))
print(coroutine.status(co2))
-- two failing __close: the last error wins
local co3 = coroutine.create(function()
  local x <close> = setmetatable({}, {__close = function(_, e) print("x sees", e); error("x failed", 0) end})
  local y <close> = setmetatable({}, {__close = function(_, e) print("y sees", e); error("y failed", 0) end})
  coroutine.yield()
end)
coroutine.resume(co3)
print(coroutine.close(co3))
-- closing the running coroutine, and a normal one, is an error
local self
self = coroutine.create(function()
  print(pcall(coroutine.close, self))
  local inner = coroutine.create(function() print(pcall(coroutine.close, self)) end)
  coroutine.resume(inner)
  return "self ok"
end)
print(coroutine.resume(self))
print(pcall(coroutine.close, coroutine.running()))
-- closing a suspended coroutine with pending pcalls and no to-be-closed variables
local co4 = coroutine.create(function()
  pcall(function() coroutine.yield("in pcall") end)
  print("never")
end)
print(coroutine.resume(co4))
print(coroutine.close(co4), coroutine.status(co4))
-- a wrapped coroutine is closed by an error inside it: its variables close with the error
local w = coroutine.wrap(function()
  local v <close> = closer("v")
  coroutine.yield(1)
  error("wrap error", 0)
end)
print(w())
print(pcall(w))
-- resume leaves the variables of a coroutine that died with an error open; close closes them
local co5 = coroutine.create(function()
  local z <close> = closer("z")
  error("unwinding", 0)
end)
print(coroutine.resume(co5))
print("before close", coroutine.status(co5))
print(coroutine.close(co5))
print(coroutine.close(co5))
return "end"
